package counter

// Max 返回切片中的最大元素。空切片或 nil 返回 0。
func Max(xs []int) int {
	if len(xs) == 0 {
		return 0
	}
	m := xs[0]
	for _, x := range xs[1:] {
		if x > m {
			m = x
		}
	}
	return m
}
--- max_test.go ---
package counter

import "testing"

func TestMax(t *testing.T) {
	if got := Max([]int{3, 9, 4}); got != 9 {
		t.Fatalf("Max(3,9,4) = %d", got)
	}
	if got := Max([]int{}); got != 0 {
		t.Fatalf("Max([]) = %d", got)
	}
	if got := Max(nil); got != 0 {
		t.Fatalf("Max(nil) = %d", got)
	}
}
